-- ============================================================================
-- portal_psa_export.sql
--
-- Read-only export of portal data needed to reconcile/seed Alga PSA.
--
-- SAFETY
--   * This file contains SELECT statements only. It must never contain
--     INSERT/UPDATE/DELETE/ALTER/DROP/TRUNCATE/GRANT/REVOKE.
--   * It forces a read-only transaction and a read-only session default.
--   * It does not use the Supabase service-role key or the REST API. Run it
--     with psql and a dedicated Postgres login that has SELECT only.
--   * The login needs to see all rows in RLS-protected tables. Provision it
--     with the built-in `pg_read_all_data` role (PostgreSQL 14+), or grant
--     SELECT plus BYPASSRLS on a read replica. Do not use a write role.
--   * No storage bytes, Stripe identifiers, payment-method identifiers,
--     encrypted PII blobs or credential/token columns are exported.
--
-- USAGE
--   mkdir -p portal-export
--   psql "$PORTAL_READONLY_DATABASE_URL" \
--     --set ON_ERROR_STOP=1 \
--     --file supabase/scripts/portal_psa_export.sql
--
--   The CSV files are written relative to the current working directory, so
--   run the command from the directory that should contain `portal-export/`.
--
-- DATA HANDLING
--   profiles.csv, memberships.csv, assets.csv, documents.csv, kb_articles.csv,
--   satisfaction_pulses.csv and the onboarding files can contain personal or
--   confidential data. Store the output encrypted, restrict access to the
--   migration owner, and delete it after reconciliation. Do not commit exports.
--
-- SCOPE
--   Organizations/memberships, billing mirror (without Stripe identifiers),
--   service catalog/products, proposals/quotes, projects/phases/tasks,
--   time entries, document metadata, both portal KB tables, assets,
--   SLA/CSAT, onboarding/M365/licence fields, vendor contracts and
--   procurement quotes. Ticket bodies/comments are intentionally out of scope;
--   use the PSA intake/backfill path for tickets.
-- ============================================================================

\set ON_ERROR_STOP on
\echo 'portal_psa_export: forcing read-only session and transaction'

begin read only;
set local statement_timeout = '30min';
set local idle_in_transaction_session_timeout = '30min';
set local client_encoding = 'UTF8';
set local timezone = 'UTC';

-- Known synthetic/demo organization IDs from supabase/seeds and the guarded
-- demo migrations. The export also honours organizations.settings.seeded and
-- row metadata.seeded, so a demo row is not treated as live data even if it
-- was inserted under a different organization.
--
-- Keep this list in sync with supabase/seeds/05, 07 and the 5302119/5302120/
-- 5302121/5302123/5302126 guarded demo migrations.
\echo 'portal_psa_export: exporting organizations'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT o.id, o.name, o.slug, o.status::text AS status, o.primary_domain, o.support_plan, (o.billing_email IS NOT NULL) AS has_billing_email, o.created_at, o.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.organizations o ORDER BY o.created_at, o.id) TO 'portal-export/organizations.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting organization_domains'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT d.id, d.organization_id, d.domain, d.auto_approve, d.created_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.organization_domains d JOIN public.organizations o ON o.id = d.organization_id ORDER BY d.organization_id, d.domain) TO 'portal-export/organization_domains.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting profiles (PII)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT p.id, p.full_name, p.email, p.phone, p.title, p.default_organization_id, p.is_super_admin, p.created_at, p.updated_at, (coalesce(p.metadata->>'seeded','') = 'true' OR p.default_organization_id IN (SELECT id FROM demo_orgs)) AS is_demo FROM public.profiles p ORDER BY p.created_at, p.id) TO 'portal-export/profiles.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting memberships'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT m.id, m.organization_id, m.user_id, r.key AS role_key, r.name AS role_name, m.status::text AS status, m.job_title, m.is_billing_contact, m.is_security_contact, m.approved_at, m.created_at, m.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(p.metadata->>'seeded','') = 'true') AS is_demo FROM public.memberships m JOIN public.roles r ON r.id = m.role_id JOIN public.organizations o ON o.id = m.organization_id LEFT JOIN public.profiles p ON p.id = m.user_id ORDER BY m.organization_id, m.created_at, m.id) TO 'portal-export/memberships.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting billing_customers (no Stripe identifiers)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT b.id, b.organization_id, (b.billing_email IS NOT NULL) AS has_billing_email, (b.stripe_customer_id IS NOT NULL) AS has_stripe_customer, (b.default_payment_method IS NOT NULL) AS has_default_payment_method, b.created_at, b.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(b.metadata->>'seeded','') = 'true') AS is_demo FROM public.billing_customers b JOIN public.organizations o ON o.id = b.organization_id ORDER BY b.organization_id) TO 'portal-export/billing_customers.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting subscriptions (no Stripe identifiers)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT s.id, s.organization_id, s.plan_name, s.status, s.current_period_start, s.current_period_end, s.amount_cents, s.currency, s.interval, s.quantity, s.cancel_at_period_end, s.canceled_at, s.trial_start, s.trial_end, s.created_at, s.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(s.metadata->>'seeded','') = 'true') AS is_demo FROM public.subscriptions s JOIN public.organizations o ON o.id = s.organization_id ORDER BY s.organization_id, s.created_at, s.id) TO 'portal-export/subscriptions.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting invoices (no Stripe identifiers/URLs)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT i.id, i.organization_id, i.invoice_number, i.status::text AS status, i.subtotal_cents, i.tax_cents, i.total_cents, i.currency, i.due_at, i.paid_at, i.voided_at, i.created_at, i.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.invoices i JOIN public.organizations o ON o.id = i.organization_id ORDER BY i.organization_id, i.created_at, i.id) TO 'portal-export/invoices.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting payments (no Stripe identifiers)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT p.id, p.organization_id, p.invoice_id, p.amount_cents, p.currency, p.status, p.paid_at, p.refund_amount_cents, p.refunded_at, p.created_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.payments p JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, p.created_at, p.id) TO 'portal-export/payments.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting service_catalog'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT s.id, s.organization_id, s.name, s.description, s.category, s.billing_model, s.unit, s.base_price, s.included_units, s.overture_rate, s.is_bundled, s.bundle_id, s.is_active, s.status, s.visibility, s.created_at, s.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(s.metadata->>'seeded','') = 'true') AS is_demo FROM public.service_catalog s JOIN public.organizations o ON o.id = s.organization_id ORDER BY s.organization_id, s.category, s.name, s.id) TO 'portal-export/service_catalog.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting vendor_contracts (reference only; not PSA client contracts)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT v.id, v.organization_id, v.vendor_name, v.service_name, v.contract_number, v.contract_type, v.contract_value, v.billing_frequency, v.start_date, v.end_date, v.renewal_date, v.renewal_notice_days, v.auto_renews, v.status, v.visibility, v.owner_user_id, v.created_by, v.created_at, v.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.vendor_contracts v JOIN public.organizations o ON o.id = v.organization_id ORDER BY v.organization_id, v.renewal_date, v.id) TO 'portal-export/vendor_contracts.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting procurement_quotes (reference only)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT q.id, q.organization_id, q.product, q.vendor_name, q.quote_amount, q.competitor_quote, q.selected, q.purchased_at, q.created_at, q.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.procurement_quotes q JOIN public.organizations o ON o.id = q.organization_id ORDER BY q.organization_id, q.created_at, q.id) TO 'portal-export/procurement_quotes.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting proposals (quote candidates)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT p.id, p.organization_id, p.title, p.description, p.status, p.visibility, p.total_labor, p.total_materials, p.total_recurring, p.total_one_time, p.grand_total, p.valid_until, p.sent_at, p.approved_at, p.rejected_at, p.expires_at, p.owner_user_id, p.created_by, p.created_at, p.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.proposals p JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, p.created_at, p.id) TO 'portal-export/proposals.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting proposal_phases'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT pp.id, pp.proposal_id, p.organization_id, pp.sort_order, pp.title, pp.description, pp.assumptions, pp.created_at, pp.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.proposal_phases pp JOIN public.proposals p ON p.id = pp.proposal_id JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, pp.proposal_id, pp.sort_order, pp.id) TO 'portal-export/proposal_phases.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting proposal_line_items'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT li.id, li.proposal_id, li.phase_id, p.organization_id, li.sort_order, li.item_type, li.name, li.description, li.quantity, li.unit_price, li.total_price, li.is_optional, li.is_recurring, li.recurring_interval, li.created_at, li.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.proposal_line_items li JOIN public.proposals p ON p.id = li.proposal_id JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, li.proposal_id, li.sort_order, li.id) TO 'portal-export/proposal_line_items.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting store_products (public catalog; no marketing assets)'
\copy (SELECT sp.id, sp.name, sp.slug, sp.category_id, sp.category, sp.type, sp.display, sp.pricing_model, sp.price_range, sp.purchase_mode, sp.status, sp.tags, sp.created_at, sp.updated_at, false AS is_demo FROM public.store_products sp ORDER BY sp.category, sp.name, sp.id) TO 'portal-export/store_products.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting store_quotes metadata (no lead PII)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT sq.id, sq.organization_id, sq.status, (CASE WHEN jsonb_typeof(sq.items) = 'array' THEN jsonb_array_length(sq.items) ELSE 0 END) AS item_count, sq.consent_at, sq.consent_version, sq.created_at, sq.updated_at, (coalesce(sq.organization_id::text,'') <> '' AND (sq.organization_id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true')) AS is_demo FROM public.store_quotes sq LEFT JOIN public.organizations o ON o.id = sq.organization_id ORDER BY sq.created_at, sq.id) TO 'portal-export/store_quotes_metadata.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting projects'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT p.id, p.organization_id, p.name, p.description, p.status::text AS status, p.priority, p.start_date, p.starts_at, p.due_date, p.due_at, p.progress_percent, p.owner_id, p.created_by, p.external_jira_project_key, p.created_at, p.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(p.metadata->>'seeded','') = 'true') AS is_demo FROM public.projects p JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, p.created_at, p.id) TO 'portal-export/projects.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting project_phases'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT ph.id, ph.project_id, p.organization_id, ph.name, ph.description, ph.start_date, ph.end_date, ph.status, ph.sort_order, ph.created_at, ph.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.project_phases ph JOIN public.projects p ON p.id = ph.project_id JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, ph.project_id, ph.sort_order, ph.id) TO 'portal-export/project_phases.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting project_milestones'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT m.id, m.project_id, m.phase_id, p.organization_id, m.title, m.description, m.due_date, m.status, m.completed_at, m.created_by, m.created_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.project_milestones m JOIN public.projects p ON p.id = m.project_id JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, m.project_id, m.due_date, m.id) TO 'portal-export/project_milestones.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting project_tasks'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT t.id, t.project_id, t.organization_id, t.parent_task_id, t.title, t.description, t.details, t.status::text AS status, t.priority, t.issue_type, t.due_date, t.due_at, t.estimate_hours, t.actual_hours, t.owner_id, t.sort_order, t.approval_required, t.approved_at, t.sprint, t.epic_key, t.labels, t.created_at, t.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true' OR coalesce(t.metadata->>'seeded','') = 'true') AS is_demo FROM public.project_tasks t JOIN public.organizations o ON o.id = t.organization_id ORDER BY t.organization_id, t.project_id, t.sort_order, t.id) TO 'portal-export/project_tasks.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting project_dependencies'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT d.id, d.project_id, p.organization_id, d.depends_on_task_id, d.depends_on_milestone_id, d.blocked_by_project_id, d.dependency_type, d.created_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.project_dependencies d JOIN public.projects p ON p.id = d.project_id JOIN public.organizations o ON o.id = p.organization_id ORDER BY p.organization_id, d.project_id, d.id) TO 'portal-export/project_dependencies.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting time_entries (no timesheet/approval data in portal)'
\copy (WITH demo_orgs AS (SELECT unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','77777777-7777-4777-8777-777777777777']::uuid[]) AS id) SELECT t.id, t.organization_id, t.ticket_id, t.user_id, t.description, t.hours, t.billable, t.work_date, t.created_at, t.updated_at, (o.id IN (SELECT id FROM demo_orgs) OR coalesce(o.settings->>'seeded','') = 'true') AS is_demo FROM public.time_entries t JOIN public.organizations o ON o.id = t.organization_id ORDER BY t.organization_id, t.work_date, t.id) TO 'portal-export/time_entries.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting documents metadata (no storage bytes)'
