\echo 'portal_psa_export: exporting public interactions metadata (no lead PII/body)'
\copy (SELECT p.id, p.status, p.urgency, p.services_requested, p.platform, p.referrer, p.is_bot, p.employees, p.consent_at, p.consent_version, (p.client_email IS NOT NULL OR p.client_phone IS NOT NULL OR p.client_name IS NOT NULL) AS has_contact_details, p.submitted_at, p.created_at, false AS is_demo FROM public.public_interactions p ORDER BY p.created_at, p.id) TO 'portal-export/public_interactions_metadata.csv' WITH (FORMAT csv, HEADER true);

\echo 'portal_psa_export: exporting ticket metadata only (bodies handled by the PSA intake path)'
