\echo 'portal_psa_export: exporting row counts'
\copy (SELECT 'organizations' AS dataset, count(*) AS row_count FROM public.organizations UNION ALL SELECT 'organization_domains', count(*) FROM public.organization_domains UNION ALL SELECT 'profiles', count(*) FROM public.profiles UNION ALL SELECT 'memberships', count(*) FROM public.memberships UNION ALL SELECT 'billing_customers', count(*) FROM public.billing_customers UNION ALL SELECT 'subscriptions', count(*) FROM public.subscriptions UNION ALL SELECT 'invoices', count(*) FROM public.invoices UNION ALL SELECT 'payments', count(*) FROM public.payments UNION ALL SELECT 'service_catalog', count(*) FROM public.service_catalog UNION ALL SELECT 'vendor_contracts', count(*) FROM public.vendor_contracts UNION ALL SELECT 'procurement_quotes', count(*) FROM public.procurement_quotes UNION ALL SELECT 'proposals', count(*) FROM public.proposals UNION ALL SELECT 'proposal_phases', count(*) FROM public.proposal_phases UNION ALL SELECT 'proposal_line_items', count(*) FROM public.proposal_line_items UNION ALL SELECT 'store_products', count(*) FROM public.store_products UNION ALL SELECT 'store_quotes', count(*) FROM public.store_quotes UNION ALL SELECT 'projects', count(*) FROM public.projects UNION ALL SELECT 'project_phases', count(*) FROM public.project_phases UNION ALL SELECT 'project_milestones', count(*) FROM public.project_milestones UNION ALL SELECT 'project_tasks', count(*) FROM public.project_tasks UNION ALL SELECT 'project_dependencies', count(*) FROM public.project_dependencies UNION ALL SELECT 'time_entries', count(*) FROM public.time_entries UNION ALL SELECT 'documents', count(*) FROM public.documents UNION ALL SELECT 'document_versions', count(*) FROM public.document_versions UNION ALL SELECT 'document_shares', count(*) FROM public.document_shares UNION ALL SELECT 'knowledge_base_articles', count(*) FROM public.knowledge_base_articles UNION ALL SELECT 'knowledge_articles', count(*) FROM public.knowledge_articles UNION ALL SELECT 'kb_article_generations', count(*) FROM public.kb_article_generations UNION ALL SELECT 'assets', count(*) FROM public.assets UNION ALL SELECT 'sla_logs', count(*) FROM public.sla_logs UNION ALL SELECT 'satisfaction_pulses', count(*) FROM public.satisfaction_pulses UNION ALL SELECT 'satisfaction_pulse_templates', count(*) FROM public.satisfaction_pulse_templates UNION ALL SELECT 'satisfaction_pulse_schedules', count(*) FROM public.satisfaction_pulse_schedules UNION ALL SELECT 'client_onboarding_command_center_records', count(*) FROM public.client_onboarding_command_center_records UNION ALL SELECT 'client_onboarding_checklist_items', count(*) FROM public.client_onboarding_checklist_items UNION ALL SELECT 'onboarding_clients', count(*) FROM public.onboarding_clients UNION ALL SELECT 'license_tracking', count(*) FROM public.license_tracking UNION ALL SELECT 'license_allocations', count(*) FROM public.license_allocations UNION ALL SELECT 'm365_hardening', count(*) FROM public.m365_hardening UNION ALL SELECT 'public_interactions', count(*) FROM public.public_interactions UNION ALL SELECT 'tickets', count(*) FROM public.tickets ORDER BY dataset) TO 'portal-export/_counts.csv' WITH (FORMAT csv, HEADER true);

commit;

\echo 'portal_psa_export: complete; verify portal-export/_counts.csv and _demo_orgs.csv'
